#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum UnitSystem {
    METRIC,
    INCH,
}

impl UnitSystem {
    pub const VALUES: [UnitSystem; 2] = [UnitSystem::METRIC, UnitSystem::INCH];
    pub fn name(&self) -> &'static str {
        match self {
            UnitSystem::METRIC => "METRIC",
            UnitSystem::INCH => "INCH",
        }
    }
    pub fn ordinal(&self) -> usize { *self as usize }
    pub fn value_of(s: &str) -> Option<Self> { Self::VALUES.iter().copied().find(|v| v.name() == s) }
    pub fn label(&self) -> &'static str {
        match self {
            UnitSystem::METRIC => "Metric (M0.25 – M64, ISO 261)",
            UnitSystem::INCH => "Inch (#0-80 – 1-3/4\" UNC/UNF, ASME B1.1)",
        }
    }
}

